// Function to parse time zone like "+05:00" or "-04:00"
const parseTimezone = (tz) => {
    const m = String(tz).match(/^[+-](\d{2})(?::?(\d{2}))?$/);
    if (m) {
        const sign = m[1] === '-' ? -1 : 1;
        const hh = parseInt(m[2], 10);
        const mm = parseInt(m[3] || '0', 10);
        return sign * (hh + mm / 60);
    }
    return 5; // default fallback
};

// Function to parse time (e.g., "Tomorrow at 5 PM")
const parseTime = (inputTime) => {
    const today = new Date();
    let timeString = inputTime.toLowerCase().includes('tomorrow') ? 'tomorrow' : 'today';

    // Extract hour and minute
    const match = inputTime.match(/(\d+)(?:[: ]?(\d{1,2}))?\s*(am|pm)/i);
    if (match) {
        let hours = parseInt(match[1]);
        let minutes = match[2] ? parseInt(match[2]) : 0;

        if (match[3] && match[3].toLowerCase() === 'pm' && hours < 12) {
            hours += 12; // Convert to 24-hour format
        } else if (match[3] && match[3].toLowerCase() === 'am' && hours === 12) {
            hours = 0; // Convert midnight hour to 0
        }

        // Set the date/time accordingly
        const date = timeString === 'tomorrow' ? new Date(today.setDate(today.getDate() + 1)) : today;
        date.setHours(hours, minutes, 0, 0); // Set the specific time

        // Add 15 minutes for the end time
        const endTime = new Date(date.getTime());
        endTime.setMinutes(endTime.getMinutes() + 15); // Add 15 minutes

        return { startTime: date, endTime: endTime }; // Return both start and end times
    }
    return null;
};

// Example input
const inputData = {
    time: "Tomorrow at 5 PM",
    email: "customer@example.com", // replace with actual email
    name: "John Doe", // replace with actual name
};

// Parse the time
const parsedTimes = parseTime(inputData.time);

// Return the output as an array with the parsed start time, end time, email, and name
return [{
    startTime: parsedTimes ? parsedTimes.startTime.toISOString() : 'Invalid time format',
    endTime: parsedTimes ? parsedTimes.endTime.toISOString() : 'Invalid time format',
    email: inputData.email,
    name: inputData.name
}];

