if (!$json.startTime || !$json.endTime) {
  return [{ json: { error: 'Missing startTime/endTime on current item' } }];
}

const start = new Date($json.startTime);  // Using $json.startTime (ISO-8601 format)
const end   = new Date($json.endTime);    // Using $json.endTime (ISO-8601 format)

// Derive "local" day boundaries from start's timezone offset
const tzOffsetMin = start.getTimezoneOffset();  // minutes offset from UTC (note: sign is opposite)
function startOfDay(dt) {
  const d = new Date(dt);
  d.setHours(0, 0, 0, 0);  // Set to midnight (start of the day)
  return d;
}
function endOfDay(dt) {
  const d = new Date(dt);
  d.setHours(23, 59, 59, 999);  // Set to the last millisecond of the day
  return d;
}

const dayStart = startOfDay(start);
const dayEnd   = endOfDay(start);

// Keep them as ISO-8601 strings
return [{
  json: {
    requestWindow: { startIso: $json.startTime, endIso: $json.endTime },
    dayStartIso: dayStart.toISOString(),
    dayEndIso: dayEnd.toISOString()
  }
}];

